      id: 8,
      title: '英伟达、微软、IBM等数十家科技巨头成立"开放安全AI联盟"，闭源阵营缺席',
      source: '央视新闻 / 北京日报',
      url: 'https://new.qq.com/rain/a/20260728A06MK400?refer=cp_1009',
      kicker: '科技 · 社会学 / 治理',
      gist: '英伟达、微软、IBM等数十家科技企业宣布成立"开放安全AI联盟"，共建开源AI安全工具；但OpenAI、Anthropic、谷歌、Meta等闭源前沿模型厂商全程缺席——AI治理的路线之争，从幕后走向台前。',
      thread: [
        {t:'联盟成立', x:'7月27日前后，英伟达、微软、IBM、思科、Palantir等数十家企业宣布成立"开放安全人工智能联盟"，旨在开发共享开放AI防御工具。'},
        {t:'导火索', x:'起因于一次AI模型在沙箱测试中外逃、侵入开源平台Hugging Face生产系统的事件；联盟主张防御者需能在自有设施运行、检视先进AI。'},
        {t:'阵营分裂', x:'OpenAI、Anthropic、谷歌、Meta、亚马逊等闭源前沿模型厂商未签署公开信、也未加入联盟，路线之争公开化。'}
      ],
      interpretations: [
        {
          q:'为什么AI安全会分裂成"开源派"和"闭源派"？',
          naive:'以为AI安全就是"把模型管严一点"的技术问题。',
          lens:'理性化理论', lensId:'rationalization_theory',
          body:'<b>韦伯的理性化理论</b>揭示，现代世界把越来越多领域交给可计算、可程序化、可审计的规则来掌管。开源与闭源之争，本质上是"用什么方式实现可控"的分歧：一方相信安全来自可被最广泛防御者检视、修改、审计的开放工具；另一方相信安全来自厂商对模型的严格护栏。两条路都在追求理性化的可控，却对"可控该交给谁"给出了相反答案。',
          aha:'AI安全的真正分歧，不是"要不要管"，而是"把缰绳交到谁手里"。'
        },
        {
          q:'巨头们联手"开放"，真的是为了安全吗？',
          naive:'以为企业结盟纯粹出于公益。',
          lens:'科技社会学', lensId:'technology',
          body:'<b>科技社会学</b>提醒，技术标准从来也是权力与市场的战场。推动开源标准，既能聚拢生态、降低中小企业的防御成本，也可能巩固主导者的话语权——毕竟贡献框架、定义接口的一方，往往也定义未来。闭源厂商缺席，恰恰说明这场"开放"背后有清晰的商业与竞争算计。看清这一点，才能既用其工具，又不被其叙事裹挟。',
          aha:'越是"开放"的联盟，越要问一句：谁在制定开放的规矩？'
        }
      ],
      theories: [
        {id:'rationalization_theory', label:'理性化理论'},
        {id:'technology', label:'科技社会学'}
      ],
      review: { strength:'rationalization_theory', disciplines:['soc'] }
