      id: 13,
      title: '政治局会议定调：加大重点群体就业支持，强化新就业形态人员权益保障',
      source: '人民日报 / 腾讯新闻',
      url: 'https://new.qq.com/rain/a/20260731A02PZ800?refer=cp_1009',
      kicker: '就业 · 经济学 / 社会',
      gist: '7月30日中共中央政治局会议强调多措并举加强民生保障，加大重点群体就业支持力度，做好灵活就业人员和新就业形态人员权益保障——在结构性转型期，"稳就业"被摆到更靠前位置。',
      thread: [
        {t:'会议定调', x:'7月30日政治局会议分析研究经济形势，强调加大重点群体就业支持力度，做好灵活就业与新就业形态人员权益保障，抓好"一老一小"服务。'},
        {t:'政策延续', x:'会议要求实施积极财政政策与适度宽松货币政策，挖掘服务消费潜力，常态化解决企业账款拖欠，提振内需。'},
        {t:'落地指向', x:'人社部等此前已推出技能照亮前程、就业服务直通车等举措，向高校毕业生、困难家庭、青年群体倾斜。'}
      ],
      interpretations: [
        {
          q:'为什么经济会议要把"就业"说得这么重？',
          naive:'以为就业只是宏观经济的一个普通指标。',
          lens:'人力资本', lensId:'econ_human_capital',
          body:'<b>人力资本</b>理论认为，劳动者通过教育、培训与健康积累的能力，是长期生产率与收入的根本来源。当会议把"重点群体就业支持""技能提升"摆在靠前位置，实质是在为结构性转型期的人力资本"充电"——让劳动者在产业更替中不掉队。对青年与困难群体而言，一次精准的培训或岗位对接，可能改写整条生命周期的收入曲线。',
          aha:'稳就业不是发救济，而是给人在变化里重新站起来的能力。'
        },
        {
          q:'为什么"灵活就业"的权益，现在必须单独被点名？',
          naive:'以为有工作就等于有保障。',
          lens:'工作社会学', lensId:'work',
          body:'<b>工作社会学</b>揭示，新就业形态把"工作"与"保障"拆开了：你每天都在劳动，却可能不隶属于任何能为你缴社保的单位。当数亿人处在这种"有活没保"的状态，权益保障就不能再默认依附于传统雇佣。会议专门点名新就业形态，是把"劳动"重新定义为值得被制度托住的事实，而不只是统计表上的一个数字。',
          aha:'保障不该问"你在哪家公司"，而该问"你是否真的在劳动"。'
        }
      ],
      theories: [
        {id:'econ_human_capital', label:'人力资本'},
        {id:'work', label:'工作社会学'}
      ],
      review: { strength:'econ_human_capital', disciplines:['econ','soc'] }
