      title: '"产教评技能生态链"发力：企业出标准、学校出学生、政府出政策破解结构性就业矛盾',
      source: '人民日报 / 人民网',
      url: 'https://paper.people.com.cn/rmrb/pc/content/202607/31/content_30172191.html',
      kicker: '教育 · 社会学 / 经济',
      gist: '《人民日报》调研"产教评技能生态链"：以企业为主体，院校、政府共同参与，产业、教学、评价衔接融通，缓解"学生就业难、企业招工难"的结构性矛盾——技能，正在被重新定义为一种可认证的资本。',
      thread: [
        {t:'矛盾显现', x:'部分制造业领域人才供需脱节：产业迭代快，院校课程设备跟不上，出现"有活没人干、有人没活干"。'},
        {t:'机制设计', x:'产教评技能生态链由链主企业出岗位、出标准、出师傅，学校出学生、出教师、出资源，政府出政策、出服务、出管理，共同促进人岗匹配。'},
        {t:'成效初显', x:'20多个省份已培育300多条生态链；东莞等地学生校内实训+企业实习，毕业即上岗，企业省去培训成本。'}
      ],
      interpretations: [
        {
          q:'为什么企业愿意亲自下场"办教育"？',
          naive:'以为育人只是学校的事。',
          lens:'文化资本', lensId:'cultural_capital',
          body:'<b>文化资本</b>理论指出，文凭与技能证书是劳动力市场上可被兑换的"通行证"。产教评生态链让企业深度参与课程与评价标准制定，本质上是把"企业需要什么能力"直接写进文化资本的认证里——学生拿到的不再是一张与企业脱节的纸，而是一份被市场即时认可的技能凭证。当学校、企业、政府共建标准，文化资本的"含金量"由最接近生产一线的人来定义。',
          aha:'最好的职业教育，是让用人单位亲自给毕业证"背书"。'
        },
        {
          q:'为什么"有人没活干、有活没人干"会同时存在？',
          naive:'以为就业难就是岗位不够。',
          lens:'新制度主义', lensId:'institutionalism',
          body:'<b>新制度主义</b>视角下，这是制度衔接的错位：教育系统的评价节奏、专业设置与产业系统的真实需求之间，缺少实时校准机制。生态链的价值，正是用一套多方协同的新制度，把"教"与"用"之间的时差压缩掉。它说明很多就业矛盾并非总量问题，而是制度接口没对上。',
          aha:'岗位从不少，少的是让"人"与"岗"对上号的那个接口。'
        }
      ],
