      id: 4,
      title: '77岁老人"免费领鸡蛋"后买下120盒羊奶粉，前员工揭会销话术套路',
      source: '新快报 / 广东广播电视台',
      url: 'https://www.toutiao.com/article/7667952771606168105/',
      kicker: '消费 · 社会学 / 经济学',
      gist: '广东一名77岁老人从"免费领鸡蛋"开始，被会销门店层层引导买下120盒羊奶粉，花费数万元；前员工爆料培训话术：先当"干儿女"嘘寒问暖，再造病情焦虑——针对老年人的情感围猎产业链再受关注。',
      thread: [
        {t:'诱饵', x:'门店以免费鸡蛋、面条吸引老人到店签到，建立联系后每日电话问候、上门陪聊，逐步培养情感依赖。'},
        {t:'收割', x:'销售以"骨密度检测""专家讲座"制造健康焦虑，宣称羊奶粉能调理多种慢病，老人陆续购买120盒，家属发现时已花费数万元。'},
        {t:'爆料', x:'前员工披露培训手册：记住老人子女姓名与病史，话术核心是"比亲儿女还亲"，业绩与情感投入直接挂钩。'},
        {t:'维权', x:'家属要求退货遭遇推诿，市场监管部门提示：会销保健品夸大功效可举报，留存录音与付款凭证是关键证据。'}
      ],
      interpretations: [
        {
          q:'销售员的嘘寒问暖为什么比子女的劝阻更"管用"？',
          naive:'以为老人只是老糊涂、贪小便宜。',
          lens:'情绪劳动', lensId:'emotional_labor',
          body:'<b>霍克希尔德的情绪劳动理论</b>指出，会销行业把"关心"变成了标准化的生产流程：微笑、陪聊、记住病史都是被培训、被考核的表演性劳动。对缺少陪伴的老人而言，这种商品化的温情精准填补了情感真空——他们买的从来不只是羊奶粉，而是一段稳定供应的"被在乎"。反诈宣传若只讲产品骗局，不解决情感缺口，收效必然有限。',
          aha:'老人不是买不起理性，是市场上只有骗子在出售陪伴。'
        },
        {
          q:'为什么"免费鸡蛋"这么小的恩惠能撬动几万元的消费？',
          naive:'以为几个鸡蛋不至于让人上钩。',
          lens:'行为经济学', lensId:'econ_behavioral',
          body:'<b>行为经济学</b>的互惠原理表明，人在接受馈赠后会产生强烈的回报义务感，且义务感与馈赠价值不成比例——鸡蛋成本几元，激活的却是"欠人情"的心理账户。再叠加每日签到的承诺一致性、现场抢购的稀缺暗示，整套会销流程就是一条精心设计的行为偏差流水线。监管此类营销，需要识别的正是这些系统性的心理杠杆。',
          aha:'鸡蛋不是赠品，是一笔高息的人情贷款。'
        }
      ],
      theories: [{id:'emotional_labor',label:'情绪劳动'},{id:'econ_behavioral',label:'行为经济学'},{id:'socialization',label:'社会化'}],
      review: {strength:'strong', disciplines:['soc','econ','psy']}
