          naive:'以为只是又一只科技股IPO。',
          lens:'供给与需求', lensId:'econ_supply_demand',
          body:'<b>供给与需求</b>视角下，DRAM长期由三星、海力士、美光三家掌控全球供给，国产供给近乎空白。长鑫量产意味着全球供给曲线多了一个自主供给源，削弱了外部断供对国内电子制造业的威胁——稀缺性的缓解本身就是市场价值的重估。',
          aha:'芯片的自主，本质是给供给安全上了一道保险。'
