          naive:'觉得只要没出事就行。',
          lens:'信息不对称', lensId:'econ_info_asym',
          body:'<b>信息不对称</b>理论指出，卖方（企业）比买方（家长）更清楚产品真实质量。当企业自检合格、监管抽检超标，家长处于信息劣势，只能靠信任或恐慌做决定——这种不对称一旦被反复消耗，市场信任就难以修复，哪怕最终产品是安全的。',
          aha:'比不合格更伤人的，是我永远不知道该信谁。'
