      interpretations: [
        {
          q:'为什么AI剪辑师暴涨，反而可能是传统剪辑师的危险信号？',
          naive:'以为多了个新岗位是好事。',
          lens:'科技社会学', lensId:'technology',
          body:'<b>科技社会学</b>强调技术不只是工具，它会重排职业的权力结构。AI把剪辑拆成生成+把关，基础执行环节被自动化吞掉，真正增值的变成了驾驭AI的人。技术没有消灭工作，却重写了谁能留在牌桌上。',
          aha:'AI不是来帮你的，是来重新定规矩的。'
        },
        {
          q:'为什么年轻人最该担心这场替代？',
          naive:'觉得AI主要替代体力活。',
          lens:'劳动力市场', lensId:'econ_labor',
          body:'<b>劳动力市场</b>中，生成式AI最先冲击的是可被编码的知识工作。斯坦福数字经济学实验室Brynjolfsson等（2025）用ADP数百万条工资记录发现，22—25岁、处在AI高暴露岗位的青年就业相对下降16%——入门级岗位正成为AI替代的煤矿金丝雀。',
          aha:'最先被AI改写简历的，恰恰是刚入场的年轻人。',
          research: { title:'Canaries in the Coal Mine? Six Facts about the Recent Employment Effects of Artificial Intelligence', authors:'Erik Brynjolfsson, Bharat Chandar, Ruyu Chen', year:2025, venue:'Stanford Digital Economy Lab', url:'https://digitaleconomy.stanford.edu/app/uploads/2025/11/CanariesintheCoalMine_Nov25.pdf', summary:'基于ADP数百万条工资记录发现，生成式AI普及后，22—25岁、处于AI高暴露岗位的青年就业相对下降约16%，且冲击集中在自动化而非增强类岗位。', fromNode:'econ_labor' }
        }
      ],
      theories: [{id:'technology',label:'科技社会学'},{id:'econ_labor',label:'劳动力市场'}],
      review: {strength:'strong', disciplines:["soc","econ"]}
