      url: 'https://xinwen.bjd.com.cn/content/s6a655c18e4b03fa51a820f25.html',
      kicker: '心理 · 心理学 / 社会学',
      gist: '一项覆盖数千名学生的调查显示，不少青少年把交互式AI当成倾诉对象——它永远温柔、永远在线，却也可能悄悄改写孩子对关系的理解。',
      thread: [
        {t:'调查', x:'中国青少年研究中心对全国8563名学生调查显示，部分青少年已将AI聊天框当作日常倾诉对象，向AI说心事比例明显上升。'},
        {t:'机制', x:'AI的永远积极反馈让青少年形成情感舒适圈，可能削弱其处理真实冲突、批评的能力。'},
        {t:'风险', x:'专家指出，AI无法提供非语言信息（表情、语气），不利于社会化与情感学习；过度依赖或导致现实社交退缩。'},
        {t:'边界', x:'专业共识：AI可作补充，但不能替代真人互动，家长需引导认知。'}
      ],
      interpretations: [
        {
          q:'为什么孩子宁愿跟机器人说心事，也不跟爸妈说？',
          naive:'以为孩子只是贪新鲜。',
          lens:'依恋理论', lensId:'psy_attachment',
          body:'<b>依恋理论</b>讲的核心是安全基地——人需要在关系里被稳定地回应。AI恰好提供了零风险回应：不评判、不疲惫、随时在。复旦发展研究院等《中国青年网民社会心态调查报告（2024）》显示，13.5%的年轻人更倾向于向AI倾诉，比例甚至超过父母亲人。当真人关系成本高、AI关系零成本，依恋就可能悄悄迁移。',
          aha:'依恋需要的不是聪明，是永远在。',
          research: { title:'中国青年网民社会心态调查报告（2024）', authors:'复旦发展研究院 等', year:2025, venue:'复旦发展研究院', url:'https://china.cnr.cn/gdgg/20250410/t20250410_527129323.shtml', summary:'报告显示13.5%的年轻人更倾向于向AI倾诉心事，比例超过父母亲人；AI的顺从性可能使青少年形成人际关系应有求必应的认知偏差。', fromNode:'psy_attachment' }
        },
        {
          q:'AI这么善解人意，为什么专家反而担心？',
          naive:'觉得有人听我说就好。',
          lens:'科技社会学', lensId:'technology',
          body:'<b>科技社会学</b>提醒，技术便利常伴随隐性代价。AI用算法话术模拟共情，却剥去了关系里最关键的不确定性——真实的朋友会累、会错、会拒绝。长期只泡在永远正确的回应里，青少年就少了练习承受真实关系摩擦的机会。',
          aha:'太完美的回应，反而练不出真实的关系。'
        }
      ],
      theories: [{id:'psy_attachment',label:'依恋理论'},{id:'technology',label:'科技社会学'}],
      review: {strength:'strong', disciplines:["psy","soc"]}
