        {t:'机制', x:'绿证代表可再生能源电力的环境权益，企业购买绿证可抵消用电的碳排放，是碳市场的重要补充。'},
        {t:'意义', x:'价格指数发布有助于形成透明价格信号，引导绿电投资与消费。'}
