          naive:'觉得环保不该谈钱。',
          lens:'环境社会学', lensId:'environment',
          body:'<b>环境社会学</b>认为，生态危机常源于环境无价——污染被默认为免费。绿证价格把碳减排变成可计量的资产，让保护行为产生经济回报，使绿水青山与金山银山在同一套账本里对话，反而激励了更多主体参与减碳。',
          aha:'给自然标价，有时是保护它的开始。'
