          body:'<b>社会资本</b>理论指出，信任、关系与人际连接本身就是稀缺资源。宠物服务、护工、陪诊这些岗位的价值，恰恰在于人与人的真实连接——这是算法最难替代的资产。老龄化与孤独社会放大了这种需求，让关系劳动升值。',
