      url: 'https://new.qq.com/rain/a/20260724A0C7ME00',
      kicker: '科技 · 心理学',
      gist: '不掉毛、不生病、永远秒回的"宠物"来了——大厂扎堆押注AI陪伴硬件，它们瞄准的不是萌，而是这个时代最普遍的孤独。',
      thread: [
        {t:'赛道', x:'多家大厂与创业公司密集发布AI宠物产品，从桌面机器人到毛绒智能体。'},
        {t:'卖点', x:'能识别情绪、记住偏好、主动撒娇互动，主打"情感陪伴"。'},
        {t:'用户', x:'独居青年、异地家庭与老年群体成为主要目标人群。'},
        {t:'市场', x:'机构预测情感陪伴类AI硬件将成为消费电子新增长点。'}
      ],
      interpretations: [
        {q:'为什么人真的会对一只"电子宠物"产生感情？',
         naive:'觉得对机器动感情很荒唐。',
         lens:'依恋理论', lensId:'psy_attachment',
         body:'<b>依恋理论</b>（鲍尔比）指出，人对"稳定回应自己的对象"会自然形成依恋——关键不在对象是谁，而在它是否可得、是否敏感回应。AI宠物恰好被设计为永远在场、永远回应、永不拒绝，精准命中依恋系统的触发机制。情感是真实的，哪怕对象是算法。',
         aha:'依恋认的不是"生命"，而是"回应"——谁稳定地回应你，谁就可能成为你的依恋对象。',
         research:{ title:'AI companions and subjective well-being: Moderation by social connectedness and loneliness', authors:'Nakagomi A., Akutsu Y., Yasuoka M., Abe N., Ihara S., Teroh T., Tabuchi T.', year:2026, venue:'Technology in Society', url:'https://doi.org/10.1016/j.techsoc.2026.103229', summary:'基于14721名日本成年人的全国性调查发现：使用AI伴侣与更高的生活满意度、幸福感和意义感显著相关，且孤独感越强的人获益越明显；朋友网络处于中等水平者受益最大，提示AI陪伴对社交需求未被满足的群体具有情感补偿价值，但需警惕其对现实社交的替代效应。', fromNode:'psy_attachment' }},
        {q:'为什么大厂集体押注的是"陪伴"而不是"功能"？',
         naive:'以为只是硬件的新噱头。',
         lens:'数字社会学', lensId:'digital',
         body:'<b>数字社会学</b>视角下，AI宠物是"孤独经济"的最新形态：城市化、独居化与原子化制造了大规模的情感缺口，而平台与硬件厂商把这个缺口识别为市场。当陪伴可以被量产和订阅，亲密关系的一部分就完成了商品化——这既是抚慰，也是收编。',
         aha:'AI宠物的商业模式，建立在一个社会学事实之上：孤独已经规模化到值得为它建一条产业链。'}
      ],
      theories: [{id:'psy_attachment',label:'依恋理论'},{id:'digital',label:'数字社会学'},{id:'technology',label:'科技社会学'}],
